import assert from 'node:assert/strict';
import {mkdir,writeFile} from 'node:fs/promises';
import {lattice,items,available,reserved} from '../demos/particle-overlap-tetrahedron/fiber-space-model.mjs';
import {faces} from '../demos/particle-overlap-tetrahedron/simplex-model.mjs';
// Necessary conditions only. No particle geometry is generated by this audit.
const table=new Map();
for(const [id,cell] of lattice.cells.entries())for(const face of faces){
 const key=face.map(i=>cell[i]).sort((a,b)=>a-b).join(',');
 if(!table.has(key))table.set(key,[]);table.get(key).push(id);
}
assert.ok([...table.values()].every(a=>a.length<=2));
const exposed=new Set([...table.values()].filter(a=>a.length===1).flat());
const candidates=[...available].map(i=>items[i]);
const layers=lattice.assembly.layers.map(l=>({items:l.items.length,cells:l.items.reduce((n,i)=>n+i.children.length,0)}));
const result={
 status:'audited',
 requested:{proton:82,neutron:126,electron:82,chains:82,witnessNeutrons:44},
 layers,
 currentAssignment:{witnessItems:reserved.size,availableItems:available.size,distinctOuterItems:reserved.size+available.size},
 // Interpreting all 126 outer items as N leaves fewer than 82 cells inside.
 neutronOuterInterpretation:{innerPrimitiveCells:layers.slice(0,-1).reduce((n,l)=>n+l.cells,0),requiredInnerProtons:82},
 // Interpreting the 82 available items as P requires actual next layers.
 protonOuterInterpretation:{
  exposedProtonCandidates:candidates.filter(i=>i.children.some(c=>exposed.has(c))).length,
  unexposedProtonCandidates:candidates.filter(i=>!i.children.some(c=>exposed.has(c))).map(i=>i.id),
  outwardNeutronLayerConstructed:false,outwardElectronLayerConstructed:false,
 },
 scope:'Boundary exposure is necessary for direct outward shared-face extension of fixed occupied items, but is not sufficient to prove collision-free extensions. No new shape, subdivision, or P/N/e identification is assumed.',
};
const out='research/strominger/results/lead208-chain-feasibility';await mkdir(out,{recursive:true});await writeFile(out+'/verification.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));
